/* ============================================================================
   REGION: SHEETS — every editor works on an in-memory buffer; the DOM never holds the truth.
   ============================================================================ */
var _SHEET=null,_lastFocus=null,_wakeLock=null;
function openSheet(kind,opts){
  /* Opening a sheet is not continued typing: release focus first, so the in-place update does not keep a stale value
     in a field that still had focus from before. */
  try{var _ae=document.activeElement;if(_ae&&_ae!==document.body&&_ae.blur&&(_ae.closest('#editBackdrop')||_ae.closest('#logBackdrop')))_ae.blur();}catch(e){}

  opts=opts||{};_lastFocus=document.activeElement;
  var isLog=kind==='log';var bd=document.getElementById(isLog?'logBackdrop':'editBackdrop');
  _SHEET={kind:kind,buf:opts.buf||{},opts:opts};
  document.getElementById(isLog?'logTitle':'editTitle').textContent=opts.title||'';document.getElementById(isLog?'logDesc':'editDesc').textContent=opts.desc||'';
  renderSheet();
  bd.classList.add('show');document.body.classList.add('sheet-open');
  setTimeout(function(){var first=bd.querySelector('input:not([type=hidden]):not(.sr-only),select,textarea,button.chip');if(first)first.focus();},40);
  _trapFocus(bd);
  if(isLog)requestWakeLock();
}
/* A modal sheet must contain the keyboard: Tab wraps inside it, Escape closes it, and focus returns to the
   control that opened it (closeSheet does that). Without a trap, Tab walks into the page behind the overlay,
   which a screen-reader or keyboard user cannot see. */
var _FOCUS_SEL='a[href],button:not([disabled]),input:not([type=hidden]):not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
var _trapHandler=null,_trapEl=null;
function _trapFocus(el){
  _untrapFocus();_trapEl=el;
  _trapHandler=function(ev){
    if(ev.key==='Escape'){ev.preventDefault();closeSheet();return;}
    if(ev.key!=='Tab')return;
    var f=Array.prototype.filter.call(el.querySelectorAll(_FOCUS_SEL),function(n){return n.offsetParent!==null||n===document.activeElement;});
    if(!f.length)return;
    var first=f[0],last=f[f.length-1];
    if(ev.shiftKey&&(document.activeElement===first||!el.contains(document.activeElement))){ev.preventDefault();last.focus();}
    else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}
    else if(!el.contains(document.activeElement)){ev.preventDefault();first.focus();}
  };
  document.addEventListener('keydown',_trapHandler,true);
}
function _untrapFocus(){if(_trapHandler)document.removeEventListener('keydown',_trapHandler,true);_trapHandler=null;_trapEl=null;}
function closeSheet(){['logBackdrop','editBackdrop'].forEach(function(id){document.getElementById(id).classList.remove('show');});document.body.classList.remove('sheet-open');_SHEET=null;_untrapFocus();releaseWakeLock();if(_lastFocus&&_lastFocus.focus){try{_lastFocus.focus();}catch(e){}}}
function sheetBodyEl(){return document.getElementById(_SHEET&&_SHEET.kind==='log'?'logBody':'editBody');}
function sheetFootEl(){return document.getElementById(_SHEET&&_SHEET.kind==='log'?'logFoot':'editFoot');}
function renderSheet(){if(!_SHEET)return;
  /* The sheet body is replaced wholesale, so the same preservation applies here. */
  var _sig=_focusSignature(document.activeElement);
  try{return _renderSheetInner();}finally{if(_sig)_restoreFocus(_sig);}
}
function _renderSheetInner(){if(!_SHEET)return;var r=SHEETS[_SHEET.opts.form||_SHEET.kind];if(!r)return;var out=r(_SHEET.buf,_SHEET.opts);setHTMLKeepingFocus(sheetBodyEl(),out.body);setHTMLKeepingFocus(sheetFootEl(),out.foot);}
function fld(name,label,o){o=o||{};var v=_SHEET.buf[name];v=v==null?'':v;var type=o.type||'text';var attrs=' id="f_'+name+'" name="'+name+'" data-act="sheet.field" data-arg="'+name+'" data-ev="'+(type==='select'?'change':'input')+'"';
  var ctl;if(type==='select')ctl='<select'+attrs+'>'+(o.options||[]).map(function(op){return '<option value="'+attrEsc(op[0])+'"'+(String(op[0])===String(v)?' selected':'')+'>'+esc(op[1])+'</option>';}).join('')+'</select>';
  else if(type==='textarea')ctl='<textarea'+attrs+' rows="'+(o.rows||3)+'" placeholder="'+attrEsc(o.placeholder||'')+'">'+esc(v)+'</textarea>';
  else ctl='<input type="'+(type==='number'?'text':type)+'"'+attrs+' value="'+attrEsc(String(v))+'"'+(type==='number'?' inputmode="'+(o.integer?'numeric':'decimal')+'"':'')+(o.placeholder?' placeholder="'+attrEsc(o.placeholder)+'"':'')+(o.list?' list="'+o.list+'"':'')+' autocomplete="off">';
  return '<div class="form-row"><label for="f_'+name+'">'+label+(o.small?' <small>'+o.small+'</small>':'')+'</label>'+ctl+(o.hint?'<div class="hint'+(o.warn?' warn':'')+'">'+o.hint+'</div>':'')+'</div>';}
function scaleRow(name,label,hint){var v=_SHEET.buf[name];var b='';for(var i=1;i<=10;i++)b+='<button type="button" data-act="sheet.scale" data-arg="'+name+'|'+i+'"'+(String(v)===String(i)?' class="active" aria-pressed="true"':' aria-pressed="false"')+' aria-label="'+label+' '+i+'">'+i+'</button>';return '<div class="form-row"><label>'+label+(hint?' <small>'+hint+'</small>':'')+'</label><div class="scale-row" role="group" aria-label="'+attrEsc(label)+'">'+b+'</div></div>';}
function setField(name,value){if(!_SHEET)return;_SHEET.buf[name]=value;if(_SHEET.opts.onField)_SHEET.opts.onField(name,value);}
var SHEETS={};
/* ---- quick log ---- */
var LOG_TYPES=[['weight','Weight'],['food','Food'],['steps','Steps'],['cardio','Cardio'],['sleep','Sleep'],['recovery','Recovery'],['hunger','Appetite'],['waist','Body'],['bodyfat','Body fat'],['supplement','Supplement'],['context','Context'],['note','Note'],['adherence','Adherence']];
function openLog(type){openSheet('log',{title:'Quick log',desc:'Choose what you observed, enter the value, save. Values are stored as observed; corrections supersede, nothing is rewritten.',buf:{type:type||'weight',date:todayISO()}});}
SHEETS.log=function(b){
  var t=b.type;var chips='<div class="chips" style="margin-bottom:12px">'+LOG_TYPES.map(function(x){return '<button type="button" class="chip'+(x[0]===t?' active':'')+'" data-act="sheet.logType" data-arg="'+x[0]+'" aria-pressed="'+(x[0]===t)+'">'+x[1]+'</button>';}).join('')+'</div>';
  var body=chips+fld('date','Date',{type:'date'});
  var last=function(tp){var l=latestObs(tp);return l?(fmtNum(tp==='weight'?fromCanonicalWeight(l.value):(/waist|neck|hip|chest|arm|thigh/.test(tp)?fromCanonicalLength(l.value):l.value),1)+' \u00b7 '+ageLabel(l.date)):'none yet';};
  if(t==='weight')body+=fld('value','Weight ('+weightUnit()+')',{type:'number',placeholder:'e.g. 262.4',hint:'last: '+last('weight')+' \u00b7 same scale, same time of day'+(b._warn?' \u00b7 '+b._warn:''),warn:!!b._warn})+fld('method','Method',{type:'select',options:[['scale','Bathroom scale'],['smart-scale','Smart scale'],['gym-scale','Gym scale'],['other','Other']]})+fld('note','Note',{placeholder:'optional'});
  else if(t==='food')body+='<div class="hint" style="margin-bottom:8px">Manual entry overrides the food log for this day. Use Food to log items with sources.</div>'+'<div class="form-pair">'+fld('calories','Calories',{type:'number',integer:true,placeholder:'kcal'})+fld('protein','Protein (g)',{type:'number',integer:true})+'</div><div class="form-trio">'+fld('carbs','Carbs (g)',{type:'number',integer:true})+fld('fat','Fat (g)',{type:'number',integer:true})+fld('fiber','Fiber (g)',{type:'number',integer:true})+'</div>'+fld('water','Water (L)',{type:'number'})+scaleRow('adherence10','Adherence today','1 = off plan \u00b7 10 = to the letter');
  else if(t==='steps')body+=fld('value','Steps',{type:'number',integer:true,placeholder:'e.g. 8500',hint:'last: '+last('steps')});
  else if(t==='cardio'){var kg=weightKgNow();var met=metFor(CARDIO_MODALITY_MET[b.modality||'walk']);var est=kg&&b.value?metKcal(met,num(b.value),kg):null;body+='<div class="form-pair">'+fld('value','Minutes',{type:'number',integer:true})+fld('modality','Modality',{type:'select',options:Object.keys(CARDIO_MODALITY_MET).map(function(k){return [k,k];})})+'</div>'+fld('rpe','RPE (1\u201310)',{type:'number',integer:true,placeholder:'5\u20136 for moderate'})+(est?'<div class="hint">Estimated energy \u2248'+fmtKcal(est*0.8,{estimate:true,bare:true})+'\u2013'+fmtKcal(est*1.2,{estimate:true})+' (MET '+met+', Compendium 2024) '+clsMark('DERIVED')+' \u2014 shown, never subtracted from intake targets.</div>':'');}
  else if(t==='sleep')body+=fld('value','Hours slept',{type:'number',placeholder:'e.g. 7.2',hint:'last: '+last('sleep')})+scaleRow('sleepq','Sleep quality');
  else if(t==='recovery')body+=scaleRow('fatigue','Fatigue','1 fresh \u00b7 10 wrecked')+scaleRow('soreness','Soreness')+scaleRow('stress','Stress')+scaleRow('motivation','Motivation');
  else if(t==='hunger')body+=scaleRow('hunger','Hunger','average over the day')+scaleRow('fullness','Fullness after meals')+scaleRow('cravings','Cravings')+scaleRow('difficulty','Difficulty sticking to the plan');
  else if(t==='waist')body+='<div class="hint" style="margin-bottom:8px">Tape at the navel, relaxed exhale, same time weekly. Neck below the larynx. Hip at the widest point.</div><div class="form-trio">'+fld('waist','Waist ('+lengthUnit()+')',{type:'number',hint:'last: '+last('waist')})+fld('neck','Neck',{type:'number',hint:'last: '+last('neck')})+fld('hip','Hip',{type:'number',hint:'last: '+last('hip')})+'</div><div class="form-trio">'+fld('chest','Chest',{type:'number'})+fld('arm','Arm',{type:'number'})+fld('thigh','Thigh',{type:'number'})+'</div>';
  else if(t==='bodyfat')body+='<div class="form-pair">'+fld('value','Body fat (%)',{type:'number'})+fld('method','Method',{type:'select',options:[['dexa','DEXA'],['bia','BIA / smart scale'],['calipers','Calipers'],['bodpod','Bod Pod'],['navy','Circumference'],['other','Other']]})+'</div><div class="hint">Methods are never compared against each other. The record keeps the method with the value.</div>';
  else if(t==='supplement')body+=fld('value','Supplement',{placeholder:'creatine 5 g',list:'suppList'})+'<datalist id="suppList"><option value="creatine 5 g"><option value="whey 30 g"><option value="caffeine 100 mg"><option value="caffeine 200 mg"><option value="vitamin D"><option value="omega-3"></datalist>';
  else if(t==='context')body+='<div class="chips" style="margin-bottom:8px">'+['travel','illness','high sodium','alcohol','holiday','new scale','creatine started','injury','poor sleep','high stress'].map(function(c){return '<button type="button" class="chip sm" data-act="sheet.ctx" data-arg="'+c+'">'+c+'</button>';}).join('')+'</div>'+fld('value','Context',{placeholder:'what changed and why it matters',hint:'context tags stop the models from blaming the plan for a travel week'});
  else if(t==='note')body+=fld('value','Note',{type:'textarea',placeholder:'free text; attached to this date'});
  else if(t==='adherence')body+=fld('value','Adherence (0\u2013100%)',{type:'number',integer:true,hint:'your own honest estimate of how closely today matched the plan'});
  return {body:body,foot:'<button class="btn btn-secondary" data-act="log.close">Cancel</button><button class="btn btn-primary" data-act="log.save">Save</button>'};
};
function saveQuickLog(force){
  /* STAGED, then committed. Every field used to be written straight through addObservation — which pushes
     to the record AND emits an event — and a later field failing validation rolled back the record with a
     splice while leaving the events behind. The live record and the event projection then disagreed inside
     the session, and persisting the log could resurrect an entry the user had abandoned. Nothing is written
     until every field has passed. */
  var b=_SHEET.buf;var t=b.type;var date=b.date||todayISO();var made=[],pending=[],warn=null;
  var add=function(type,value,extra){if(value==null||value==='')return;var tt=OBS_TYPES[type];if(!tt.text){var n=num(value);if(n==null){warn='"'+value+'" is not a number';return;}if(!force&&(n<tt.min||n>tt.max)){warn=tt.label+' '+n+' is outside the plausible range ('+tt.min+'\u2013'+tt.max+' '+tt.unit+')';return;}if(!force){var oc=outlierCheck(type,n,date);if(oc.outlier)warn=tt.label+': '+oc.note;}if(warn&&!force)return;pending.push(Object.assign({type:type,date:date,value:n},extra||{}));}else pending.push(Object.assign({type:type,date:date,value:String(value)},extra||{}));};
  pushUndo('quick log');
  if(t==='weight')add('weight',toCanonicalWeight(b.value),{method:b.method||'scale',note:b.note});
  else if(t==='food'){add('calories',b.calories);add('protein',b.protein);add('carbs',b.carbs);add('fat',b.fat);add('fiber',b.fiber);add('water',b.water);if(b.adherence10)add('adherence',num(b.adherence10)*10);}
  else if(t==='steps')add('steps',b.value);
  else if(t==='cardio')add('cardio',b.value,{method:b.modality||'walk',meta:{rpe:num(b.rpe)}});
  else if(t==='sleep'){add('sleep',b.value);add('sleepq',b.sleepq);}
  else if(t==='recovery'){add('fatigue',b.fatigue);add('soreness',b.soreness);add('stress',b.stress);add('motivation',b.motivation);}
  else if(t==='hunger'){add('hunger',b.hunger);add('fullness',b.fullness);add('cravings',b.cravings);add('difficulty',b.difficulty);}
  else if(t==='waist'){['waist','neck','hip','chest','arm','thigh'].forEach(function(k){if(b[k]!=null&&b[k]!=='')add(k,toCanonicalLength(b[k]),{method:'tape'});});}
  else if(t==='bodyfat')add('bodyfat',b.value,{method:b.method||'other'});
  else if(t==='supplement')add('supplement',b.value);
  else if(t==='context')add('context',b.value);
  else if(t==='note')add('note',b.value);
  else if(t==='adherence')add('adherence',b.value);
  if(warn&&!force){pending.length=0;_SHEET.buf._warn=warn;renderSheet();sheetFootEl().innerHTML='<button class="btn btn-secondary" data-act="log.close">Cancel</button><button class="btn btn-primary" data-act="log.saveAnyway">Save anyway</button>';return;}
  if(!pending.length){_SHEET.buf._warn='nothing to save';renderSheet();return;}
  /* Commit point: past here every field validated, so the record and the event log move together. */
  pending.forEach(function(spec){made.push(addObservation(spec,{noSave:true,silent:true}));});
  if(!made.length){_SHEET.buf._warn='nothing to save';renderSheet();return;}
  save('quick-log');_memoInvalidate();closeSheet();renderAll();toast('Logged '+made.length+' observation'+(made.length>1?'s':'')+(made.some(function(m){return m.flags.length;})?' (flagged for review)':''),{undo:true});
}
