SHEETS.profile=function(b){var body=fld('name','Name')+'<div class="form-trio">'+fld('age','Age',{type:'number',integer:true})+fld('sex','Sex',{type:'select',options:[['','\u2014'],['male','Male'],['female','Female']]})+(unitPref()==='metric'?fld('height','Height (cm)',{type:'number'}):fld('heightFt','Height (ft)',{type:'number',integer:true}))+'</div>'+(unitPref()==='metric'?'':fld('heightIn','+ inches',{type:'number'}))+'<div class="form-pair">'+fld('startWeight','Start weight ('+weightUnit()+')',{type:'number'})+fld('goalWeight','Goal weight ('+weightUnit()+')',{type:'number'})+'</div>'+fld('targetDate','Target date',{type:'date',hint:'optional; the engine flags a required rate that is unrealistic'})+fld('activityBaseline','Activity baseline (outside training)',{type:'select',options:Object.keys(ACTIVITY_FACTORS).map(function(k){return [k,ACTIVITY_FACTORS[k].label];})})+'<div class="form-pair">'+fld('trainingExperience','Training experience',{type:'select',options:[['','\u2014'],['novice','Novice (<1 yr)'],['novice-intermediate','Novice-intermediate'],['intermediate','Intermediate (1\u20133 yr)'],['advanced','Advanced']]})+fld('sleepTargetH','Sleep target (h)',{type:'number'})+'</div><div class="form-pair">'+fld('dietPreference','Diet preference')+fld('equipment','Equipment')+'</div>'+fld('schedule','Schedule constraints',{placeholder:'e.g. 2-2-3 rotating shifts'});return {body:body,foot:'<button class="btn btn-secondary" data-act="edit.close">Cancel</button><button class="btn btn-primary" data-act="profile.save">Save profile</button>'};};
/* The profile is written in one place, used by the Profile sheet and by the welcome setup alike. */
