var _RCP={ingSearch:'',local:[],branded:[],state:'idle'};
function openRecipe(id){var r=id?DB.recipes.filter(function(x){return x.id===id;})[0]:null;_RCP={ingSearch:'',local:[],branded:[],state:'idle'};openSheet('edit',{form:'recipe',title:r?'Edit recipe':'New recipe',desc:'Each ingredient is measured in its own basis (g, mL or servings); totals divide by servings. Logging a serving stores a snapshot.',buf:{id:r?r.id:null,name:r?r.name:'',servings:r?r.servings:4,ingredients:r?r.ingredients.map(function(i){var q=_ingQty(i);return {food:normalizeFood(i.food),quantity:q.qty,basis:q.basis,grams:q.basis==='g'?q.qty:null};}):[]}});}
SHEETS.recipe=function(b){var t=recipeTotals(b);var body='<div class="form-pair">'+fld('name','Recipe name')+fld('servings','Servings',{type:'number',integer:true})+'</div>'+(b.ingredients.length?b.ingredients.map(function(i,idx){var q=_ingQty(i);return '<div class="set-grid" style="grid-template-columns:3fr 1fr auto"><span style="font-size:13px">'+esc(i.food.name)+' <span class="muted">'+(q.basis==='ml'?'mL':(q.basis==='serving'?'servings':'g'))+'</span></span><input type="text" inputmode="decimal" value="'+q.qty+'" aria-label="quantity in '+(q.basis==='ml'?'millilitres':(q.basis==='serving'?'servings':'grams'))+'" data-act="sheet.ing" data-arg="'+idx+'" data-ev="input"><button type="button" class="btn btn-ghost btn-sm" data-act="sheet.ingDel" data-arg="'+idx+'" aria-label="remove">\u2715</button></div>';}).join(''):'<div class="muted">No ingredients yet.</div>')+'<div class="row"><div class="l">Per serving</div><div class="r"><strong>'+fmtNum(t.perServing.kcal,0)+' kcal</strong><small>P '+fmtNum(t.perServing.protein,0)+' \u00b7 C '+fmtNum(t.perServing.carbs,0)+' \u00b7 F '+fmtNum(t.perServing.fat,0)+' \u00b7 '+(t.massKnown?fmtNum(t.gramsPerServing,0)+' g':'mass unknown (volume ingredients)')+'</small></div></div><div class="form-row"><label for="rcp_q">Add ingredient</label><input id="rcp_q" type="search" value="'+attrEsc(_RCP.q||'')+'" placeholder="search" data-act="recipe.search" data-ev="input" autocomplete="off"></div><div id="rcp_results">'+renderRecipeResults()+'</div>';return {body:body,foot:'<button class="btn btn-secondary" data-act="edit.close">Cancel</button><button class="btn btn-primary" data-act="recipe.save">Save recipe</button>'};};
function renderRecipeResults(){var R=_RCP;if(!R.q||R.q.length<2)return '';return (R.local.concat(R.branded)).slice(0,12).map(function(f){return '<div class="food-item" data-act="recipe.addIng" data-arg="'+attrEsc(f.kind+'|'+f.id)+'" tabindex="0" role="button"><div><div class="fi-name">'+esc(f.name)+'</div><div class="fi-src">'+esc(f.source)+'</div></div><div class="fi-kcal">'+foodKcalLabel(f)+'</div></div>';}).join('')+(R.state==='loading'?'<div class="muted">searching branded\u2026</div>':'');}
function saveRecipeSheet(){var b=_SHEET.buf;if(!b.name||!b.ingredients.length){toast('Name and at least one ingredient',{tone:'negative'});return;}saveRecipe({id:b.id,name:b.name.trim(),servings:Math.max(1,num(b.servings)||1),ingredients:b.ingredients.map(function(i){var q=_ingQty(i);return {food:foodSnapshot(i.food),quantity:q.qty,basis:q.basis,grams:q.basis==='g'?q.qty:null};})});closeSheet();renderAll();toast('Recipe saved');}
/* ---- custom food ---- */
SHEETS.customFood=function(b){return {body:fld('name','Food name')+fld('basis','Values are per',{type:'select',options:[['100','100 g'],['100ml','100 mL (liquid, labelled by volume)'],['serving','one serving (by weight)'],['servingml','one serving (by volume)']]})+(b.basis==='serving'?fld('servingG','Serving size (g)',{type:'number'}):'')+(b.basis==='servingml'?fld('servingMl','Serving size (mL)',{type:'number'}):'')+'<div class="form-pair">'+fld('kcal','Calories',{type:'number'})+fld('protein','Protein (g)',{type:'number'})+'</div><div class="form-pair">'+fld('carbs','Carbs (g)',{type:'number'})+fld('fat','Fat (g)',{type:'number'})+'</div><div class="form-pair">'+fld('fiber','Fiber (g)',{type:'number'})+fld('sodium','Sodium (mg)',{type:'number'})+'</div><div class="hint">Stored as USER ENTERED with today\u2019s date as its version.</div>',foot:'<button class="btn btn-secondary" data-act="edit.close">Cancel</button><button class="btn btn-primary" data-act="food.customSave">Save food</button>'};};
function saveCustomFood(){var b=_SHEET.buf;if(!b.name){toast('Name required',{tone:'negative'});return;}var f=1;var sg=num(b.servingG),sm=num(b.servingMl);var basis=(b.basis==='100ml'||b.basis==='servingml')?'ml':'g';if(b.basis==='serving'){if(!sg){toast('Serving size in grams is required',{tone:'negative'});return;}f=100/sg;}if(b.basis==='servingml'){if(!sm){toast('Serving size in mL is required',{tone:'negative'});return;}f=100/sm;}var per={};['kcal','protein','carbs','fat','fiber','sodium'].forEach(function(k){var v=num(b[k]);per[k]=v==null?null:round(v*f,2);});var portions=[];if(basis==='g'&&sg)portions.push({label:'1 serving',g:sg,serving:true});if(basis==='ml'&&sm)portions.push({label:'1 serving',ml:sm,serving:true});var food=saveUserFood({name:b.name.trim(),category:'My foods',basis:basis,per100:per,portions:portions,servingGrams:basis==='g'?sg:null,servingMl:basis==='ml'?sm:null,perServing:(basis==='g'&&sg)?_scaleNutrients(per,sg/100):((basis==='ml'&&sm)?_scaleNutrients(per,sm/100):null),source:'USER',version:todayISO(),energySource:'user'});closeSheet();renderAll();toast('Saved '+esc(food.name));}
/* ---- restore preview ---- */
SHEETS.restore=function(b){var p=b.preview;return {body:'<div class="lead" style="font-size:13px">File: <b>'+esc(b.fileName)+'</b> \u00b7 schema '+esc(String(p.schemaVersion))+' \u00b7 app '+esc(String(p.appVersion))+'</div>'+kv([['observations',p.counts.observations],['sessions',p.counts.sessions],['food items',p.counts.foodLogs],['phases',p.counts.phases],['predictions',p.counts.predictions],['experiments',p.counts.experiments],['created',esc(String(p.createdAt||'\u2014'))],['validation',p.valid?'passed':('failed: '+esc(p.errors.join('; ')))]])+'<div class="divider"></div>'+fld('mode','How to apply',{type:'select',options:[['merge','Merge: add records not already present (recommended)'],['replace','Replace: the file becomes the record']]})+'<div class="hint">A backup of the current record is written to IndexedDB first. This can be undone.</div>',foot:'<button class="btn btn-secondary" data-act="edit.close">Cancel</button><button class="btn btn-primary" data-act="data.restoreApply"'+(p.valid?'':' disabled')+'>Apply</button>'};};
/* ---- confirm / prompt ---- */
var _confirmResolve=null,_promptResolve=null;
function confirmDialog(o){return new Promise(function(res){_confirmResolve=res;document.getElementById('confirmTitle').textContent=o.title||'Confirm';document.getElementById('confirmMsg').innerHTML=o.msg||'';var ok=document.getElementById('confirmOk');ok.textContent=o.okLabel||'Continue';ok.className='btn '+(o.danger?'btn-danger':'btn-primary');document.getElementById('confirmBackdrop').classList.add('show');setTimeout(function(){ok.focus();},30);});}
function resolveConfirm(v){document.getElementById('confirmBackdrop').classList.remove('show');if(_confirmResolve){var r=_confirmResolve;_confirmResolve=null;r(v);}}
function promptDialog(o){return new Promise(function(res){_promptResolve=res;document.getElementById('promptTitle').textContent=o.title||'Enter a value';document.getElementById('promptLabel').textContent=o.label||'Value';var inp=document.getElementById('promptInput');inp.value=o.value!=null?o.value:'';inp.type=o.type||'text';if(o.inputmode)inp.setAttribute('inputmode',o.inputmode);document.getElementById('promptBackdrop').classList.add('show');setTimeout(function(){inp.focus();inp.select();},30);});}
function resolvePrompt(v){document.getElementById('promptBackdrop').classList.remove('show');if(_promptResolve){var r=_promptResolve;_promptResolve=null;r(v);}}
/* ---- wake lock while logging ---- */
function requestWakeLock(){try{if(navigator.wakeLock&&navigator.wakeLock.request){navigator.wakeLock.request('screen').then(function(l){_wakeLock=l;}).catch(function(){});}}catch(e){}}
function releaseWakeLock(){try{if(_wakeLock){_wakeLock.release();_wakeLock=null;}}catch(e){}}
